def store_turn_to_supermemory(client_id, user_text, assistant_text, request_id):
    api_key = _env("SUPERMEMORY_API_KEY", "").strip()
    if not api_key:
        return
    container_tag = supermemory_container_tag(client_id)
    meta_base = {
        "source": "bedrock-claude-opus-4-5",
        "request_id": request_id,
        "ts_ms": _now_ms()
    }
    if isinstance(user_text, str) and user_text.strip():
        supermemory_add_document(api_key, container_tag, user_text, {**meta_base, "role": "user"})
    if isinstance(assistant_text, str) and assistant_text.strip():
        supermemory_add_document(api_key, container_tag, assistant_text, {**meta_base, "role": "assistant"})

def invoke_bedrock(messages, system=None, max_tokens=64000, temperature=1.0, top_p=1.0, region=None, model_id=None, api_key=None, timeout=3600):
    if not api_key or not isinstance(api_key, str) or not api_key.strip():
        return {"ok": False, "status": 500, "error": {"message": "AWS_BEARER_TOKEN_BEDROCK is not set"}}
    region = (region if isinstance(region, str) and region.strip() else "us-east-1")
    model_id = (model_id if isinstance(model_id, str) and model_id.strip() else "global.anthropic.claude-opus-4-5-20251101-v1:0")
    host = "bedrock-runtime." + region + ".amazonaws.com"
    path = "/model/" + model_id + "/invoke"
    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages),
        "temperature": float(temperature),
        "top_p": float(top_p)
    }
    if isinstance(system, str) and system.strip():
        body["system"] = system
    payload = json.dumps(body)
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": "Bearer " + api_key,
        "x-amz-bedrock-api-version": "2023-10-01"
    }
    conn = http.client.HTTPSConnection(host, timeout=timeout)
    try:
        conn.request("POST", path, body=payload, headers=headers)
        resp = conn.getresponse()
        status = resp.status
        raw = resp.read()
        ctype = resp.getheader("Content-Type", "application/json")
    finally:
        conn.close()
    if int(status) != 200:
        err = _safe_json_loads(raw)
        if err is None:
            err = {"message": raw.decode("utf-8", errors="ignore")}
        return {"ok": False, "status": int(status), "error": err}
    if "application/json" in (ctype or ""):
        data = _safe_json_loads(raw)
        if isinstance(data, dict):
            return {"ok": True, "status": 200, "data": data}
    return {"ok": True, "status": 200, "data": {"raw": raw.decode("utf-8", errors="ignore")}}

def extract_anthropic_text(data):
    if not isinstance(data, dict):
        return str(data)
    content = data.get("content")
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                parts.append(item["text"])
        return "".join(parts)
    raw = data.get("raw")
    if isinstance(raw, str):
        return raw
    return json.dumps(data, ensure_ascii=False)

