@app.route("/api/chat", methods=["POST"])
def api_chat():
    request_id = str(uuid.uuid4())
    api_key = _env("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    region = _env("AWS_REGION", "us-east-1").strip() or "us-east-1"
    model_id = _env("BEDROCK_MODEL_ID", "global.anthropic.claude-opus-4-5-20251101-v1:0").strip() or "global.anthropic.claude-opus-4-5-20251101-v1:0"
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = {}
    client_id = payload.get("client_id")
    if not isinstance(client_id, str) or not client_id.strip():
        client_id = _env("SUPERMEMORY_USER_ID", "").strip() or str(uuid.uuid4())
    messages = payload.get("messages")
    prompt = payload.get("prompt")
    system = payload.get("system")
    if not isinstance(messages, list) or len(messages) == 0:
        if isinstance(prompt, str) and prompt.strip():
            messages = [{"role": "user", "content": prompt}]
        else:
            return jsonify({"error": "messages or prompt is required", "request_id": request_id}), 400
    last_user = _extract_last_user_text(messages)
    memory_block = ""
    if supermemory_enabled() and isinstance(last_user, str) and last_user.strip():
        memory_block = build_memory_block(client_id, last_user.strip())
    system_base = system if isinstance(system, str) else ""
    system_full = ""
    if memory_block:
        system_full = memory_block + "\n\n" + system_base
    else:
        system_full = system_base
    result = invoke_bedrock(
        messages=messages,
        system=system_full,
        max_tokens=int(_env("MAX_TOKENS", "64000") or "64000"),
        temperature=float(_env("TEMPERATURE", "1.0") or "1.0"),
        top_p=float(_env("TOP_P", "1.0") or "1.0"),
        region=region,
        model_id=model_id,
        api_key=api_key,
        timeout=int(_env("BEDROCK_TIMEOUT", "3600") or "3600")
    )
    if not result.get("ok"):
        status = int(result.get("status") or 500)
        return jsonify({"error": result.get("error"), "status": status, "request_id": request_id}), status
    data = result.get("data", {})
    text = extract_anthropic_text(data)
    store_turn_to_supermemory(client_id, last_user, text, request_id)
    usage = {}
    if isinstance(data, dict) and isinstance(data.get("usage"), dict):
        usage = data["usage"]
    return jsonify({"output_text": text, "usage": usage, "model_id": model_id, "region": region, "request_id": request_id, "client_id": client_id})

